import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Goftego — Self-hosted Chat Platform","description":"A lightweight self-hosted chat platform: channels, realtime WebSocket fan-out, JWT auth, presence and typing indicators — one SQLite file, bilingual fa/en with RTL.","frontmatter":{"title":"Goftego — Self-hosted Chat Platform","description":"A lightweight self-hosted chat platform: channels, realtime WebSocket fan-out, JWT auth, presence and typing indicators — one SQLite file, bilingual fa/en with RTL."},"headers":[],"relativePath":"en/projects/goftego/index.md","filePath":"en/projects/goftego/index.md"}`),a={name:`en/projects/goftego/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="goftego-—-self-hosted-chat-platform" tabindex="-1">Goftego — Self-hosted Chat Platform <a class="header-anchor" href="#goftego-—-self-hosted-chat-platform" aria-label="Permalink to “Goftego — Self-hosted Chat Platform”">​</a></h1><p><strong><a href="https://github.com/Godde3s/goftego" target="_blank" rel="noreferrer">Goftego</a></strong> (گفتگو — <em>conversation</em>) is what a small community gets instead of surrendering its conversations to a SaaS: a <strong>one-command, own-your-data chat platform</strong>. Channels, realtime delivery, presence counts, typing indicators, JWT auth with bcrypt-hashed passwords — all stored in <strong>one SQLite file</strong> with WAL mode, zero external services.</p><h2 id="the-stack" tabindex="-1">The stack <a class="header-anchor" href="#the-stack" aria-label="Permalink to “The stack”">​</a></h2><ul><li><strong>Server</strong> — Node.js (ESM): Express REST API, a WebSocket hub (<code>join</code> / <code>leave</code> / <code>typing</code> / <code>post</code> → persist → fan-out), <code>better-sqlite3</code> with foreign keys and indexes, bcrypt cost 12, JWT verified on both REST and the WS handshake.</li><li><strong>Client</strong> — Vue 3 SPA: reactive store without a state library, bilingual <strong>fa (RTL) / en</strong> UI switchable in one click, dark theme, mobile-friendly.</li><li><strong>Deploy</strong> — multi-stage Dockerfile (build the SPA, serve it from the API server) + <code>docker compose up</code>.</li></ul><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">     # → http://localhost:3000</span></span></code></pre></div><h2 id="details-i-sweated" tabindex="-1">Details I sweated <a class="header-anchor" href="#details-i-sweated" aria-label="Permalink to “Details I sweated”">​</a></h2><p>Messages posted over REST and over WebSockets flow through <strong>one persistence path</strong>, so the WS broadcast and the SQL insert can never disagree. The realtime hub re-verifies JWTs per connection, presence counts update on leave/disconnect, and the client reconnects its socket per channel switch. The Vue client talks Persian-first: <code>&lt;html dir=&quot;rtl&quot;&gt;</code>, Vazirmatn font, Persian placeholders — English is one toggle away.</p><p><strong>7 vitest tests</strong> cover the auth flow, channel CRUD, message paging and validation. This is my reference full-stack build: database, API, realtime, SPA, i18n, containers — the whole loop. MIT licensed.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};